:root{--cream:#FFF6EC;--coral:#FF5E3A;--sun:#FFC23C;--ink:#25163A;--pink:#FF8FB1;--teal:#22B8A8;--lilac:#8B6CFF}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
html,body{overflow-x:hidden}
body{font-family:Heebo,system-ui,Arial,sans-serif;background:var(--cream);color:var(--ink);line-height:1.45}
a{color:inherit;text-decoration:none}
#m{width:100%}
#prog{position:fixed;top:0;right:0;height:4px;width:100%;transform-origin:right;transform:scaleX(0);background:linear-gradient(90deg,var(--sun),var(--coral),var(--pink));z-index:50}
section{position:relative;padding:64px 20px;max-width:980px;margin:0 auto}
h2{font-weight:900;font-size:clamp(28px,7vw,48px);line-height:1.08;margin-bottom:12px}
h2 em{font-style:normal;background:linear-gradient(90deg,var(--coral),var(--pink));-webkit-background-clip:text;background-clip:text;color:transparent}
.sub{font-size:17px;opacity:.78;margin-bottom:24px;max-width:640px}
.rv{opacity:0;transform:translateY(40px);transition:opacity .65s ease var(--d,0ms),transform .7s ease var(--d,0ms)}
.rv.in{opacity:1;transform:none}
.hero{min-height:92svh;display:flex;flex-direction:column;justify-content:center;padding:48px 20px 56px;max-width:980px;margin:0 auto;position:relative}
.blob{position:absolute;border-radius:50%;filter:blur(44px);opacity:.5;z-index:-1;animation:drift 14s ease-in-out infinite alternate}
.b1{width:280px;height:280px;background:var(--sun);top:-40px;left:-60px}
.b2{width:240px;height:240px;background:var(--pink);top:35%;right:-100px;animation-delay:-4s}
@keyframes drift{to{transform:translate(36px,48px) scale(1.12)}}
.kicker{display:inline-flex;align-items:center;gap:8px;background:#fff;border-radius:99px;padding:7px 14px;font-weight:700;font-size:14px;box-shadow:0 4px 18px rgba(37,22,58,.08)}
.kicker i{width:9px;height:9px;border-radius:50%;background:var(--coral);animation:pulse 1.4s infinite}
@keyframes pulse{50%{transform:scale(1.5);opacity:.45}}
.hero h1{font-weight:900;font-size:clamp(40px,11vw,72px);line-height:1;letter-spacing:-.5px;margin:14px 0 8px}
.hero h1 .accent{color:var(--coral)}
.hero .tag{font-size:clamp(18px,4.5vw,22px);font-weight:700;max-width:520px}
.hero .tag span{background:linear-gradient(transparent 62%,rgba(255,194,60,.75) 62%)}
.hero-meta{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0 26px}
.pill{background:#fff;border-radius:99px;padding:8px 14px;font-weight:800;font-size:14px;box-shadow:0 6px 20px -10px rgba(37,22,58,.25)}
.hero-row{display:flex;flex-wrap:wrap;align-items:center;gap:28px;margin-top:8px}
.bunny{width:88px;height:88px;border-radius:24px;box-shadow:0 16px 40px -12px rgba(255,94,58,.5)}
.cta{display:inline-flex;align-items:center;justify-content:center;gap:10px;background:#25D366;color:#fff;font-weight:900;font-size:19px;padding:16px 26px;border-radius:99px;box-shadow:0 12px 28px -8px rgba(37,211,102,.65);transition:transform .2s}
.cta svg{width:24px;height:24px}
.cta:active{transform:scale(.97)}
.cta.sec{background:var(--ink);box-shadow:0 12px 28px -10px rgba(37,22,58,.45)}
.wrow{display:flex;align-items:flex-start;gap:14px;background:#fff;border-radius:22px;padding:16px 18px;margin-bottom:12px;box-shadow:0 8px 28px -14px rgba(37,22,58,.18)}
.wrow .e{font-size:32px;flex:none;width:52px;height:52px;display:grid;place-items:center;border-radius:16px;background:var(--cream)}
.wrow b{font-size:19px;font-weight:900;display:block;margin-bottom:2px}
.wrow span{font-size:15px;opacity:.72}
.lessons{display:grid;gap:16px}
@media(min-width:720px){.lessons{grid-template-columns:repeat(3,1fr)}}
.lesson{background:#fff;border-radius:24px;padding:22px 20px;box-shadow:0 10px 32px -16px rgba(37,22,58,.22);border:2px solid transparent}
.lesson b{display:block;font-size:13px;font-weight:800;color:var(--coral);margin-bottom:6px}
.lesson h3{font-size:20px;font-weight:900;margin-bottom:10px;line-height:1.15}
.lesson ul{list-style:none;font-size:14px;opacity:.85}
.lesson li{padding:4px 0;padding-right:14px;position:relative}
.lesson li::before{content:"·";position:absolute;right:0;color:var(--coral);font-weight:900}
.price-box{background:linear-gradient(145deg,#fff,#FFF8F0);border:3px solid var(--sun);border-radius:28px;padding:28px 22px;text-align:center;max-width:420px;margin:0 auto}
.price-box .num{font-size:52px;font-weight:900;line-height:1}
.price-box .vat{font-size:15px;opacity:.75;margin:8px 0 16px}
.price-box .note{font-size:14px;opacity:.8}
.bonus-grid{display:grid;gap:12px}
@media(min-width:600px){.bonus-grid{grid-template-columns:1fr 1fr}}
.bonus{background:#fff;border-radius:20px;padding:16px 18px;font-size:15px}
.bonus strong{display:block;font-size:17px;margin-bottom:4px}
.faq details{background:#fff;border-radius:18px;padding:14px 18px;margin-bottom:10px;box-shadow:0 4px 20px -12px rgba(37,22,58,.12)}
.faq summary{font-weight:800;cursor:pointer;list-style:none}
.faq summary::-webkit-details-marker{display:none}
.faq p{margin-top:10px;font-size:15px;opacity:.85}
.demo{margin-top:20px;border-radius:24px;overflow:hidden;box-shadow:0 20px 50px -24px rgba(37,22,58,.35);max-width:360px}
.demo video{width:100%;aspect-ratio:9/16;object-fit:cover;background:#000}
.proof{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px}
.proof span{background:var(--ink);color:#fff;border-radius:14px;padding:10px 14px;font-weight:800;font-size:14px}
.notfor{opacity:.85;font-size:15px;line-height:1.6}
.notfor b{color:var(--coral)}
.final{text-align:center;padding-bottom:80px}
.ig{display:flex;flex-wrap:wrap;justify-content:center;gap:16px;padding:24px;font-weight:800}
.foot{text-align:center;font-size:14px;opacity:.65;padding-bottom:32px}
.sticky.cta{position:fixed;bottom:16px;left:16px;right:16px;z-index:40;font-size:17px;opacity:0;pointer-events:none;transform:translateY(20px);transition:.35s}
.sticky.cta.show{opacity:1;pointer-events:auto;transform:none}
@media(min-width:640px){.sticky.cta{left:auto;right:24px;max-width:320px}}

(()=>{
const io=new IntersectionObserver(es=>es.forEach(e=>{
  if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}
}),{threshold:.12,rootMargin:'0px 0px -5% 0px'});
document.querySelectorAll('.rv').forEach(el=>io.observe(el));
const prog=document.getElementById('prog'),hero=document.querySelector('.hero'),sticky=document.querySelector('.cta.sticky');
function onS(){
  const y=scrollY,h=document.documentElement.scrollHeight-innerHeight;
  if(prog)prog.style.transform='scaleX('+(h>0?y/h:0)+')';
  if(sticky&&hero)sticky.classList.toggle('show',y>hero.offsetHeight*.65);
}
addEventListener('scroll',onS,{passive:true});
onS();
})();

