/* סדנה — שכבה על ig-landing (פאני באני) */
.audience{display:grid;gap:14px;margin-top:22px}
@media(min-width:720px){.audience{grid-template-columns:repeat(2,1fr)}}
@media(min-width:960px){.audience{grid-template-columns:repeat(4,1fr)}}
.audience article{padding:18px 16px;border-radius:var(--radius);background:var(--glass);border:1px solid var(--line);box-shadow:0 12px 40px -24px rgba(0,0,0,.5)}
.audience b{display:block;font-size:19px;margin-bottom:6px}
.audience span{color:var(--muted);font-size:15px;line-height:1.45}
.ba-sec{text-align:center}
.ba-sec p.hint{margin-bottom:18px}
.lab-ba{--p:50%;position:relative;direction:ltr;width:min(340px,92vw);aspect-ratio:9/16;margin:0 auto;border-radius:22px;overflow:hidden;background:#12082a;box-shadow:0 24px 60px -18px rgba(255,79,180,.45);touch-action:pan-y;cursor:ew-resize;user-select:none}
.lab-ba video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none}
.lab-ba .top{clip-path:inset(0 calc(100% - var(--p)) 0 0)}
