/* סדנת פאני באני — רילים + לפני/אחרי + סטיקי WA */
(function () {
  const WA = '972515688377';
  const wa = (t) => 'https://wa.me/' + WA + '?text=' + encodeURIComponent(t);

  /* רילים: סאונד בלחיצה, טעינה בגלילה */
  const vids = [...document.querySelectorAll('video[data-src]')];
  const vo = new IntersectionObserver(
    (es) =>
      es.forEach((e) => {
        const v = e.target;
        if (e.isIntersecting) {
          if (!v.src) v.src = v.dataset.src;
          v.play()?.catch(() => {});
        } else v.pause();
      }),
    { threshold: 0.35 }
  );
  vids.forEach((v) => vo.observe(v));
  document.querySelectorAll('.vwrap').forEach((w) => {
    const v = w.querySelector('video');
    const b = w.querySelector('.snd');
  if (!v || !b) return;
    const tog = (ev) => {
      ev.preventDefault();
      const on = v.muted;
      vids.forEach((o) => {
        if (o !== v) {
          o.muted = true;
          const ob = o.parentNode.querySelector('.snd');
          if (ob) {
            ob.classList.remove('on');
            ob.querySelector('.ic').textContent = '🔇';
          }
        }
      });
      v.muted = !on;
      if (on) {
        if (!v.src) v.src = v.dataset.src;
        v.currentTime = 0;
        v.play()?.catch(() => {});
      }
      b.classList.toggle('on', on);
      b.querySelector('.ic').textContent = on ? '🔊' : '🔇';
    };
    w.addEventListener('click', tog);
  });

  /* לפני / אחרי */
  const ba = document.getElementById('labBa');
  if (ba) {
    const raw = document.getElementById('baRaw');
    const ed = document.getElementById('baEdit');
    let touched = false;
    const setP = (v) => ba.style.setProperty('--p', Math.max(3, Math.min(97, v)).toFixed(1) + '%');
    const fromX = (e) => {
      const r = ba.getBoundingClientRect();
      setP(((e.clientX - r.left) / r.width) * 100);
    };
    ba.addEventListener('pointerdown', (e) => {
      touched = true;
      ba.setPointerCapture(e.pointerId);
      fromX(e);
    });
    ba.addEventListener('pointermove', (e) => {
      if (ba.hasPointerCapture(e.pointerId)) fromX(e);
    });
    if (raw && ed) {
      raw.addEventListener('timeupdate', () => {
        if (Math.abs(raw.currentTime - ed.currentTime) > 0.12) ed.currentTime = raw.currentTime;
      });
      new IntersectionObserver(
        (es) => {
          const on = es[0].isIntersecting;
          [raw, ed].forEach((v) => {
            if (on) {
              if (v.preload === 'none') {
                v.preload = 'auto';
                v.load();
              }
              v.play()?.catch(() => {});
            } else v.pause();
          });
        },
        { threshold: 0.2 }
      ).observe(ba);
      if (!matchMedia('(prefers-reduced-motion: reduce)').matches) {
        const t0 = performance.now();
        const f = (now) => {
          if (touched) return;
          const k = (now - t0) / 3000;
          if (k >= 1) {
            setP(50);
            return;
          }
          setP(50 + 40 * Math.sin(k * Math.PI * 2));
          requestAnimationFrame(f);
        };
        requestAnimationFrame(f);
      }
    }
  }

  /* סטיקי WA */
  const sticky = document.querySelector('.sticky');
  const heroBtn = document.querySelector('.hero .btn.wa');
  const fin = document.querySelector('.final');
  if (sticky && heroBtn && fin && 'IntersectionObserver' in window) {
    const seen = { hero: true, fin: false };
    const io2 = new IntersectionObserver((es) => {
      es.forEach((e) => {
        if (e.target === heroBtn) seen.hero = e.isIntersecting;
        else seen.fin = e.isIntersecting;
      });
      sticky.classList.toggle('hide', seen.hero || seen.fin);
    });
    io2.observe(heroBtn);
    io2.observe(fin);
    sticky.classList.add('hide');
  }

  document.querySelectorAll('[data-wa-msg]').forEach((el) => {
    el.addEventListener('click', (e) => {
      if (el.tagName === 'A') return;
      e.preventDefault();
      const msg = el.getAttribute('data-wa-msg');
      if (msg) window.open(wa(msg), '_blank', 'noopener');
    });
  });
})();

