/* ===== the AI scan (pinned scroll scene) ===== */
#scan{padding:0;height:290svh;background:#08061a;position:relative}
.scan-pin{position:sticky;top:0;height:100svh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:clamp(12px,3svh,26px);overflow:hidden;color:#fff;background:radial-gradient(70% 42% at 50% 40%,rgba(255,94,58,.42),transparent 72%),#08061a}
.scan-pin::before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(185,170,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(185,170,255,.07) 1px,transparent 1px);background-size:34px 34px;-webkit-mask-image:radial-gradient(70% 55% at 50% 42%,#000,transparent);mask-image:radial-gradient(70% 55% at 50% 42%,#000,transparent)}
.scan-box{position:relative;width:min(76vw,(100svh - 190px)*.79,440px);aspect-ratio:760/960}
.scan-box{border-radius:26px;transition:box-shadow .5s ease}
.scan-box img{position:absolute;inset:0;width:100%;height:100%;max-width:none;border-radius:26px;object-fit:cover;will-change:opacity}
.scan-box canvas{position:absolute;inset:0;width:100%;height:100%}
.scan-box.done{box-shadow:0 0 70px -6px rgba(255,94,58,.75)}
.scan-bar{position:absolute;left:-7%;right:-7%;top:0;height:3px;background:linear-gradient(90deg,transparent,#fff 22%,#fff 78%,transparent);box-shadow:0 0 26px 8px rgba(255,94,58,.9);opacity:0;will-change:transform,opacity}
.scan-wave{position:absolute;left:10%;right:10%;bottom:3%;height:15%;display:flex;gap:2.2%;align-items:center;justify-content:center;opacity:0;transition:opacity .3s}
.scan-wave i{flex:1;height:100%;border-radius:4px;background:linear-gradient(#fff,#FFC23C);transform:scaleY(.08);will-change:transform}
.scan-tag{position:absolute;top:4%;left:50%;translate:-50% 0;white-space:nowrap;background:var(--primary);color:#fff;font-size:16px;font-weight:700;padding:7px 18px;border-radius:999px;box-shadow:0 10px 30px -6px rgba(255,94,58,.95);opacity:0;transform:scale(.7);transition:opacity .35s,transform .45s cubic-bezier(.2,1.6,.4,1)}
.scan-box.done .scan-tag{opacity:1;transform:none}
.scan-lines{position:relative;height:1.3em;width:min(100%,92vw);font-size:clamp(25px,7vw,44px);font-weight:300;text-align:center;letter-spacing:-.01em}
.scan-lines p{position:absolute;inset:0;opacity:0;transform:translate3d(0,20px,0);transition:opacity .35s ease,transform .35s ease;white-space:nowrap}
.scan-lines p.on{opacity:1;transform:none}
.scan-lines b{font-weight:800;color:var(--coral)}
#scan.static{height:auto}
#scan.static .scan-pin{position:relative;height:auto;padding:44px 20px}
#scan.static .scan-lines{height:auto}
#scan.static .scan-lines p{position:static;opacity:1;transform:none;white-space:normal;font-size:.7em;margin-top:8px}
/* scroll reveals (Roei) */
#prog{position:fixed;top:0;right:0;left:0;height:3px;z-index:90;background:linear-gradient(270deg,#FF5E3A,#FFC23C 60%,#FF8FB1);transform:scaleX(0);transform-origin:right;pointer-events:none}
.sell-roei .w{display:inline-block;overflow:hidden;vertical-align:top;padding:.08em 0 .2em;margin:-.08em 0 -.2em}
.sell-roei .w>span{display:inline-block;transform:translate3d(0,120%,0);transition:transform .75s cubic-bezier(.2,.85,.25,1);will-change:transform}
.sell-roei h2.on .w>span{transform:none}
.sell-roei h2.wd.rv{opacity:1;transform:none}
.sell-roei .rv.fx-tilt{transform:perspective(900px) rotateX(20deg) translate3d(0,44px,0);transform-origin:50% 100%}
.sell-roei .rv.fx-zoom{transform:scale(.84)}
.sell-roei .rv.fx-side{transform:translate3d(46px,0,0)}
.sell-roei .rv.fx-up{transform:translate3d(0,40px,0)}
.sell-roei .rv.fx-tilt.on,.sell-roei .rv.fx-zoom.on,.sell-roei .rv.fx-side.on,.sell-roei .rv.fx-up.on{transform:none}
#tracks.curtain{clip-path:inset(0 7% round 34px);transition:clip-path 1s cubic-bezier(.2,.8,.2,1)}
#tracks.curtain.on{clip-path:inset(0 0 round 0)}
.sell-roei .eyebrow.typing::after{content:"";display:inline-block;width:2px;height:1em;margin-inline-start:3px;vertical-align:-2px;background:currentColor;animation:caret .7s steps(2) infinite}
@keyframes caret{50%{opacity:0}}
@media (prefers-reduced-motion:reduce){.sell-roei .w>span{transform:none}#tracks.curtain{clip-path:none}#prog{display:none}}
@media(max-width:640px){
  .sell-roei > #scan{padding:0!important;height:200svh}
  .scan-lines p{white-space:normal;font-size:clamp(18px,5vw,22px)}
}

