/* אחידות: פונט + רספונסיב + בלוקי רועי בתוך עיצוב פאני באני */

:root {
  --fs-body: clamp(16px, 4.1vw, 18px);
  --fs-lead: clamp(17px, 4.4vw, 20px);
  --fs-h2: clamp(28px, 7.2vw, 50px);
  --fs-h3: clamp(20px, 5.2vw, 26px);
  --fw-regular: 400;
  --fw-bold: 700;
  --fw-black: 900;
  --page-pad: 20px;
  --section-y: clamp(44px, 10vw, 72px);
}

body {
  font-size: var(--fs-body);
  font-weight: var(--fw-regular);
}

/* רק משקלים שנטענו (400 / 700 / 900) — בלי סינתזה מגעילה */
.sell-roei,
.sell-roei .wrap {
  font-family: Heebo, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
  font-weight: var(--fw-regular);
  -webkit-font-smoothing: antialiased;
}

.sell-roei b,
.sell-roei strong,
.sell-roei h2,
.sell-roei h3,
.sell-roei .tk-h b,
.sell-roei .counter b,
.sell-roei .bigprice .amt,
.sell-roei .px-num,
.sell-roei .burn .big b,
.sell-roei .side .n,
.sell-roei .count b,
.sell-roei .tk-cd b {
  font-weight: var(--fw-black);
}

.sell-roei h2 {
  font-size: var(--fs-h2);
  font-weight: var(--fw-black);
  line-height: 1.08;
  letter-spacing: -0.02em;
  text-align: center;
  text-wrap: balance;
  max-width: 22ch;
  margin-inline: auto;
  margin-bottom: 12px;
  color: var(--text, #fff);
}

.sell-roei h2 b {
  font-weight: var(--fw-black);
  color: var(--gold, #ffd60a);
}

.sell-roei h2 mark {
  font-weight: var(--fw-black);
}

.sell-roei h3,
.sell-roei .step h3 {
  font-size: var(--fs-h3);
  font-weight: var(--fw-bold);
}

.sell-roei .sub,
.sell-roei .fitline,
.sell-roei .calc-note,
.sell-roei .lab-note {
  font-size: var(--fs-lead);
  font-weight: var(--fw-regular);
  color: var(--muted, #cfc4ee);
  text-align: center;
  margin-inline: auto;
  max-width: 38ch;
  line-height: 1.5;
  text-wrap: balance;
}

.sell-roei .eyebrow {
  font-weight: var(--fw-bold);
  font-size: 13px;
}

/* פריסה: יוצאים מרוחב ה-main בלי לשבור גלילה */
.sell-roei {
  margin-inline: calc(-1 * var(--page-pad));
  width: calc(100% + 2 * var(--page-pad));
  max-width: 100vw;
  overflow-x: clip;
}

.sell-roei .wrap {
  width: min(1080px, 100% - 32px);
  margin-inline: auto;
  padding-inline: 0;
}

.sell-roei section {
  padding: var(--section-y) 0;
}

.sell-roei > #scan {
  margin-inline: calc(50% - 50vw);
  width: 100vw;
  max-width: 100vw;
  padding: 0 !important;
}

#tracks.ofr {
  margin-inline: calc(50% - 50vw);
  width: 100vw;
  max-width: 100vw;
  box-sizing: border-box;
  padding-inline: var(--page-pad);
}

#tracks.curtain {
  clip-path: none;
}

#tracks.curtain.on {
  clip-path: none;
}

/* כרטיסים כהים במקום לבן ישן */
.sell-roei .inputs,
.sell-roei .calc .inputs {
  background: rgba(255, 255, 255, 0.06) !important;
  border: 1px solid var(--line, rgba(255, 255, 255, 0.13)) !important;
  color: #fff;
}

.sell-roei .field label {
  font-weight: var(--fw-bold);
  font-size: clamp(15px, 3.8vw, 18px);
}

.sell-roei .field label output {
  font-weight: var(--fw-black);
  font-size: clamp(22px, 6vw, 30px);
}

.sell-roei .field small {
  color: var(--dim, #a99bd3);
}

.sell-roei .side.now,
.sell-roei .side.av {
  border-radius: 18px;
}

.sell-roei .side h3 {
  font-weight: var(--fw-bold);
}

.sell-roei .side .n {
  font-weight: var(--fw-black);
  font-size: clamp(22px, 6vw, 30px);
}

.sell-roei .side p {
  font-size: clamp(14px, 3.6vw, 16px);
  font-weight: var(--fw-regular);
}

.sell-roei .burn .k,
.sell-roei .burn .year {
  font-weight: var(--fw-regular);
  font-size: clamp(14px, 3.6vw, 16px);
}

.sell-roei .counter {
  font-weight: var(--fw-regular);
  font-size: clamp(18px, 4.5vw, 22px);
  text-wrap: balance;
  padding-inline: 12px;
}

.sell-roei .step p,
.sell-roei .syl-b,
.sell-roei .incl li,
.sell-roei .chat .q,
.sell-roei .chat .a {
  font-size: clamp(16px, 4.1vw, 18px);
  font-weight: var(--fw-regular);
}

.sell-roei .viz {
  background: rgba(0, 0, 0, 0.25);
  border-color: var(--line, rgba(255, 255, 255, 0.12));
}

.sell-roei .pain {
  padding-inline: var(--page-pad);
}

.sell-roei .pain-lines {
  text-align: center;
  gap: clamp(12px, 3vw, 22px);
}

.sell-roei .pain-lines p {
  font-size: clamp(22px, 6.2vw, 40px);
  font-weight: var(--fw-bold);
  line-height: 1.15;
  text-wrap: balance;
  letter-spacing: -0.02em;
}

.sell-roei .pain-lines p:last-child {
  font-weight: var(--fw-black);
  color: var(--pink, #ff4fb4);
}

.sell-roei .scan-lines {
  font-weight: var(--fw-bold);
  height: auto;
  min-height: 2.6em;
  padding-inline: 12px;
}

.sell-roei .scan-lines p {
  white-space: normal;
  text-wrap: balance;
  font-size: clamp(17px, 4.6vw, 24px);
  font-weight: var(--fw-bold);
  line-height: 1.25;
  padding-inline: 8px;
}

.sell-roei .lab-card h3 {
  font-weight: var(--fw-black);
  text-align: center;
  text-wrap: balance;
}

.sell-roei .lab-work {
  grid-template-columns: 1fr !important;
  min-height: 0;
}

.sell-roei .lab-phone {
  max-width: 220px;
  margin-inline: auto;
}

.sell-roei .faq details summary {
  font-weight: var(--fw-bold);
  font-size: clamp(17px, 4.4vw, 20px);
}

.sell-roei .cost h2 {
  max-width: none;
}

.sell-roei .now p.big {
  font-weight: var(--fw-bold);
  font-size: clamp(22px, 5.8vw, 34px);
  max-width: 28ch;
}

.sell-roei .roei-btn {
  font-weight: var(--fw-black) !important;
  font-size: clamp(16px, 4.2vw, 18px) !important;
  max-width: 100%;
}

.ofr .bigprice .amt {
  font-weight: var(--fw-black);
}

.ofr .tk-h {
  font-weight: var(--fw-black);
}

/* ===== מובייל ===== */
@media (max-width: 760px) {
  :root {
    --section-y: 40px;
    --page-pad: 16px;
  }

  main {
    padding-inline: var(--page-pad);
  }

  .sell-roei {
    margin-inline: calc(-1 * var(--page-pad));
    width: calc(100% + 2 * var(--page-pad));
  }

  .sell-roei > #scan {
    height: min(200svh, 1800px) !important;
  }

  .scan-box {
    width: min(88vw, 360px);
  }

  .calc {
    grid-template-columns: 1fr !important;
    gap: 16px !important;
    margin-top: 18px !important;
  }

  .vs {
    grid-template-columns: 1fr !important;
  }

  .stage {
    width: 100%;
    margin-top: 20px;
  }

  .steps {
    padding-right: 40px;
    gap: 20px;
    margin-top: 22px;
  }

  .step .dot {
    width: 32px;
    height: 32px;
    right: -40px;
    font-size: 14px;
    font-weight: var(--fw-black);
  }

  .step p {
    max-width: none;
  }

  .chat {
    margin-top: 20px;
    gap: 18px;
  }

  .chat .q,
  .chat .a {
    max-width: 94%;
    font-size: 16px;
  }

  .bigprice .amt {
    font-size: clamp(52px, 15vw, 72px) !important;
  }

  .ticket {
    margin-top: 28px;
  }

  .tk-in {
    padding: 24px 16px 20px;
  }

  .incl {
    padding: 18px 16px;
  }

  .outcome {
    grid-template-columns: 1fr !important;
  }

  .outcome div {
    font-weight: var(--fw-bold);
    font-size: 16px;
  }

  .syl-item summary {
    min-height: auto;
    padding: 12px 0;
  }

  .syl-t {
    font-size: 17px !important;
    font-weight: var(--fw-bold) !important;
  }

  .count {
    flex-wrap: wrap;
    gap: 8px;
  }

  .count div {
    min-width: 72px;
    flex: 1 1 72px;
  }

  .hero h1 {
    font-size: clamp(32px, 9.2vw, 42px);
  }

  .stats {
    grid-template-columns: 1fr;
    max-width: 280px;
  }

  .reel {
    flex: 0 0 82%;
    max-width: 280px;
  }

  .ba-sec .lab-ba {
    width: min(300px, 88vw);
  }
}

@media (min-width: 761px) {
  .calc {
    grid-template-columns: 0.95fr 1.05fr;
  }

  .sell-roei .lab-work {
    grid-template-columns: 1fr 150px !important;
  }

  .lab-grid--solo .lab-work {
    grid-template-columns: 1fr min(200px, 28vw) !important;
  }
}

@media (min-width: 900px) {
  .sell-roei h2 {
    max-width: 24ch;
  }

  .outcome {
    grid-template-columns: repeat(3, 1fr);
  }

  .ofr .pay-btns {
    grid-template-columns: 1fr 1fr;
  }
}

